CFLAGS_SAVE="$CFLAGS"
CXXFLAGS_SAVE="$CXXFLAGS"
unset CFLAGS
unset CXXFLAGS
export AFL_NOOPT=1
export CXXFLAGS="-stdlib=libc++"
cd $SRC/libpcap-1.9.1
./configure --disable-shared
make -j$(nproc)
make install
cd $SRC/zeromq-4.3.4
./autogen.sh
./configure --without-documentation --without-libsodium --enable-static --disable-shared
make -j$(nproc)
make install
cd $SRC/json-c-json-c-0.16-20220414
mkdir build
cd build
cmake -DBUILD_SHARED_LIBS=OFF ..
make -j$(nproc)
make install
cd $SRC/libmaxminddb-1.7.1
./configure --disable-shared --enable-static
make -j$(nproc)
make install
cd $NDPI_HOME
./autogen.sh
make -j$(nproc)
make -C $NTOPNG_HOME/third-party/lua-5.4.3 generic
cd $NTOPNG_HOME/third-party/rrdtool-1.4.8
./configure --disable-libdbi --disable-libwrap --disable-rrdcgi --disable-libtool-lock     --disable-nls --disable-rpath --disable-perl --disable-ruby --disable-lua     --disable-tcl --disable-python --disable-dependency-tracking --disable-rrd_graph
cd src
make librrd_th.la
export CFLAGS="${CFLAGS_SAVE}"
export CXXFLAGS="${CXXFLAGS_SAVE}"
unset AFL_NOOPT
cd $NTOPNG_HOME
./autogen.sh
./configure --enable-fuzztargets --without-hiredis --with-zmq-static     --with-json-c-static --with-maxminddb-static
make -j$(nproc) fuzz_all
find fuzz/ -regex 'fuzz/fuzz_[a-z_]*' -exec cp {} {}.dict {}_seed_corpus.zip $OUT/ \;
mkdir -p $OUT/install $OUT/data-dir $OUT/docs $OUT/scripts/callbacks
